  const amountInCents = Math.round(input.amount * 100);
  const idempotencyKey = input.idempotencyKey ?? IdempotencyManager.generateTransactionKey(
    input.senderAccountNumber.toString(),
    input.receiverAccountNumber.toString(),
    amountInCents,
  ).key;

  const existing = await this.idempotencyRepo.findByKey(idempotencyKey);
  if (existing) {
    if (existing.status === "completed") {
      return existing.result as ITransaction;
    }
    throw new Error("Concurrent transfer in progress for the same idempotency key");
  }

  await this.idempotencyRepo.create({
    key: idempotencyKey,
    operation: "transaction",
    status: "pending",
    createdAt: new Date(),
    updatedAt: new Date(),
    expiresAt: new Date(Date.now() + 24 * 60 * 60 * 1000),
  });

